package encstore

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"sync"
	"time"
)

// SecureStore provides encrypted file storage with atomic write semantics
type SecureStore struct {
	mu       sync.RWMutex
	baseDir  string
	key      []byte
	tempDir  string
	fileMode os.FileMode
}

// NewSecureStore creates a new encrypted storage instance
func NewSecureStore(baseDir string, masterKey []byte) (*SecureStore, error) {
	hash := sha256.Sum256(masterKey)
	key := hash[:]

	tempDir := filepath.Join(baseDir, ".tmp")
	if err := os.MkdirAll(tempDir, 0700); err != nil {
		return nil, fmt.Errorf("failed to create temp directory: %w", err)
	}

	if err := os.MkdirAll(baseDir, 0700); err != nil {
		return nil, fmt.Errorf("failed to create base directory: %w", err)
	}

	return &SecureStore{
		baseDir:  baseDir,
		key:      key,
		tempDir:  tempDir,
		fileMode: 0600,
	}, nil
}

// generateTempPath creates a unique temporary file path
func (s *SecureStore) generateTempPath(name string) string {
	timestamp := time.Now().UnixNano()
	nameHash := sha256.Sum256([]byte(name))
	prefix := hex.EncodeToString(nameHash[:8])
	return filepath.Join(s.tempDir, fmt.Sprintf("%s_%d.tmp", prefix, timestamp))
}

// encrypt performs AES-GCM encryption
func (s *SecureStore) encrypt(plaintext []byte) ([]byte, error) {
	block, err := aes.NewCipher(s.key)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonce := make([]byte, gcm.NonceSize())
	if _, err := io.ReadFull(rand.Reader, nonce); err != nil {
		return nil, err
	}

	return gcm.Seal(nonce, nonce, plaintext, nil), nil
}

// decrypt performs AES-GCM decryption
func (s *SecureStore) decrypt(ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(s.key)
	if err != nil {
		return nil, err
	}

	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}

	nonceSize := gcm.NonceSize()
	if len(ciphertext) < nonceSize {
		return nil, fmt.Errorf("ciphertext too short")
	}

	nonce, ciphertext := ciphertext[:nonceSize], ciphertext[nonceSize:]
	return gcm.Open(nil, nonce, ciphertext, nil)
}

// WriteSecret atomically writes encrypted data to the store
func (s *SecureStore) WriteSecret(name string, data []byte) error {
	s.mu.Lock()
	defer s.mu.Unlock()

	encrypted, err := s.encrypt(data)
	if err != nil {
		return fmt.Errorf("encryption failed: %w", err)
	}

	tempPath := s.generateTempPath(name)

	// Create temp file with restricted permissions for atomic write
	// Using os.Create then chmod for cross-platform compatibility
	f, err := os.Create(tempPath)
	if err != nil {
		return fmt.Errorf("failed to create temp file: %w", err)
	}

	if _, err := f.Write(encrypted); err != nil {
		f.Close()
		os.Remove(tempPath)
		return fmt.Errorf("failed to write temp file: %w", err)
	}

	if err := f.Sync(); err != nil {
		f.Close()
		os.Remove(tempPath)
		return fmt.Errorf("failed to sync temp file: %w", err)
	}

	if err := f.Chmod(s.fileMode); err != nil {
		f.Close()
		os.Remove(tempPath)
		return fmt.Errorf("failed to set permissions: %w", err)
	}

	f.Close()

	finalPath := filepath.Join(s.baseDir, name+".enc")
	if err := os.Rename(tempPath, finalPath); err != nil {
		os.Remove(tempPath)
		return fmt.Errorf("failed to finalize write: %w", err)
	}

	return nil
}

// ReadSecret reads and decrypts data from the store
func (s *SecureStore) ReadSecret(name string) ([]byte, error) {
	s.mu.RLock()
	defer s.mu.RUnlock()

	finalPath := filepath.Join(s.baseDir, name+".enc")
	ciphertext, err := os.ReadFile(finalPath)
	if err != nil {
		return nil, fmt.Errorf("failed to read secret: %w", err)
	}

	plaintext, err := s.decrypt(ciphertext)
	if err != nil {
		return nil, fmt.Errorf("decryption failed: %w", err)
	}

	return plaintext, nil
}

// CleanupStale removes temporary files older than maxAge
func (s *SecureStore) CleanupStale(maxAge time.Duration) error {
	entries, err := os.ReadDir(s.tempDir)
	if err != nil {
		return err
	}

	for _, entry := range entries {
		info, err := entry.Info()
		if err != nil {
			continue
		}
		if time.Since(info.ModTime()) > maxAge {
			os.Remove(filepath.Join(s.tempDir, entry.Name()))
		}
	}
	return nil
}
